js.text:

function grid$dmvb(f){
  this.constructor(f);
}
grid$dmvb.prototype = new DirEvent();
grid$dmvb.prototype.afterInit = function(){
  var p = this._dir;
}

css.text:

.tree-form{
	width: 250px;
}
.ic-view-dept{
  background-position: 0px 0px;
}
.table-bottom{
	left: 0px!important;
	height: calc(100% - 77px);
	top: 0px;
	position: relative;
	margin-top: 27px;
	clear: both;
	border-bottom: 1px solid #ddd;
}
#content .dir{
	position: relative !important;
	height: 100%;
}

@media only screen and (max-width: 960px) {
  .table-bottom{
	margin-top: 42px;
	height: calc(100% - 92px);
  }
}
